"use strict";

// OpenClaw Hook：rustdesk-free-memory-trigger
// 教練說「釋放記憶體」時直接執行 RustDesk 重啟腳本，不靠模型自己判斷。
// 2026-08-27 建立：教練糾正「每10分鐘檢查一次」太浪費，改成事件觸發
// （教練自己目視 Activity Monitor，看到高就說這句話，AI 才動手）。
// 事件：message:preprocessed（照 rule-reminder / project-card-router 模板）

const { execFileSync } = require("child_process");
const path = require("path");

const HOME = process.env.HOME;
const SCRIPT_PATH = path.join(HOME, ".openclaw", "workspace", "scripts", "rustdesk_free_memory.sh");
const SCRIPT_PATH_ALL = path.join(HOME, ".openclaw", "workspace", "scripts", "release_all_memory.sh");
// 2026-09-02教練定義「全部釋放」＝關瀏覽器/赫米斯/LINE/Typeless四個常駐App+重啟RustDesk
// 這組要先判斷，因為文字裡也含「釋放」，若不優先判斷會被下面的單純RustDesk規則搶先命中
const TRIGGER_ALL_RE = /全部釋放|釋放全部|通通釋放|全都釋放|全面釋放/;
// 2026-08-27 教練要求簡化：「釋放」兩個字單獨講也要能觸發，不用每次都講全「釋放記憶體」
const TRIGGER_RE = /釋放記憶體|放記憶體|釋放|RustDesk.{0,6}(重啟|釋放|清)|清.{0,4}RustDesk/;

function extractText(event) {
  const c = (event && event.context) || {};
  const cands = [
    event.text,
    c.text, c.content, c.prompt, c.input, c.transcript, c.userText, c.body, c.userMessage,
    (c.message && (typeof c.message === "string" ? c.message : (c.message.text || c.message.content))),
  ];
  const pickLast = (arr) => {
    if (Array.isArray(arr) && arr.length) {
      const last = arr[arr.length - 1];
      if (typeof last === "string") return last;
      if (last && typeof last === "object") return last.text || last.content || "";
    }
    return "";
  };
  cands.push(pickLast(event.messages));
  cands.push(pickLast(c.messages));
  for (const v of cands) if (typeof v === "string" && v.trim()) return v;
  return "";
}

// 沿用 bot-relay-inbound / rule-reminder 已驗證的三層 fallback（案例56教訓：
// LINE default帳號 sessionKey 是 agent:main:line:...，解析出來就是 "main"）
function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    "";
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || "";
  if (sessionKey) {
    const parts = String(sessionKey).split(":");
    if (parts[0] === "agent" && parts[1]) return parts[1].toLowerCase();
  }
  return "unknown";
}

const handler = async (event) => {
  try {
    const agentId = resolveAgentId(event);
    if (agentId !== "main") return event; // 只對教練自己的帳號生效

    const text = extractText(event);
    if (!text) return event;

    const isAll = TRIGGER_ALL_RE.test(text);
    const isRustDeskOnly = !isAll && TRIGGER_RE.test(text);
    if (!isAll && !isRustDeskOnly) return event;

    const scriptPath = isAll ? SCRIPT_PATH_ALL : SCRIPT_PATH;
    const timeout = isAll ? 30000 : 20000;

    let output;
    try {
      output = execFileSync("/bin/bash", [scriptPath], {
        timeout,
        encoding: "utf8",
      }).trim();
    } catch (execErr) {
      output = `執行失敗：${execErr && execErr.message ? execErr.message : String(execErr)}`;
    }

    const ctx = event.context || (event.context = {});
    if (!ctx.inject) ctx.inject = [];
    if (Array.isArray(ctx.inject)) {
      ctx.inject.push({
        role: "system",
        content: isAll
          ? `🖥️ 教練說了「全部釋放」，已直接執行 scripts/release_all_memory.sh（關瀏覽器/赫米斯/LINE/Typeless+重啟RustDesk），` +
            `真實結果如下，請照實轉述給教練，不要自己編數字：\n${output}`
          : `🖥️ 教練說了「釋放記憶體」，已直接執行 scripts/rustdesk_free_memory.sh，` +
            `真實結果如下，請照實轉述給教練，不要自己編數字：\n${output}`,
      });
    }
    return event;
  } catch (err) {
    return event;
  }
};

module.exports = handler;
module.exports.default = handler;

